import Foundation
import SwiftUI

enum AppLanguage: String, CaseIterable {
    case english = "en"
    case spanish = "es"
    case swedish = "sv"
    case french = "fr"
    case german = "de"
    
    var displayName: String {
        switch self {
        case .english: return "English"
        case .spanish: return "Spanish"
        case .swedish: return "Swedish"
        case .french: return "French"
        case .german: return "German"
        }
    }
    
    var flag: String {
        switch self {
        case .english: return "🇬🇧"
        case .spanish: return "🇪🇸"
        case .swedish: return "🇸🇪"
        case .french: return "🇫🇷"
        case .german: return "🇩🇪"
        }
    }
}

class LanguageManager: ObservableObject {
    @Published var currentLanguage: AppLanguage {
        didSet {
            UserDefaults.standard.set(currentLanguage.rawValue, forKey: "SelectedLanguage")
            loadLocalizations()
        }
    }
    
    private var localizations: [String: String] = [:]
    
    init() {
        // Load saved language or default to English
        if let savedLanguage = UserDefaults.standard.string(forKey: "SelectedLanguage"),
           let language = AppLanguage(rawValue: savedLanguage) {
            self.currentLanguage = language
        } else {
            self.currentLanguage = .english
        }
        loadLocalizations()
    }
    
    private func loadLocalizations() {
        switch currentLanguage {
        case .english:
            localizations = EnglishLocalization.dictionary
        case .spanish:
            localizations = SpanishLocalization.dictionary
        case .swedish:
            localizations = SwedishLocalization.dictionary
        case .french:
            localizations = FrenchLocalization.dictionary
        case .german:
            localizations = GermanLocalization.dictionary
        }
    }
    
    func localizedString(for key: String) -> String {
        return localizations[key] ?? key
    }
    
    // Convenience method for SwiftUI
    func localized(_ key: String) -> String {
        return localizedString(for: key)
    }
}

